using ghidra.util.task;

/**
 * Identifies functions to which Jump references exist and converts the
 * associated branching instruction flow to a CALL-RETURN
 */
public class SharedReturnAnalyzer : AbstractAnalyzer {

	private static readonly string NAME = "Shared Return Calls";
	protected static readonly string DESCRIPTION =
		"Converts branches to calls, followed by an immediate return, when the destination is a function.  " +
			"Since this analysis is triggered by the creation of the destination function, " +
			"the one-shot analysis action can be used if functions were created while this " +
			"analyzer was disabled or not present.";

	private static string OPTION_NAME_ASSUME_CONTIGUOUS_FUNCTIONS =
		"Assume Contiguous Functions Only";

	private static string OPTION_NAME_CONSIDER_CONDITIONAL_BRANCHES_FUNCTIONS =
		"Allow Conditional Jumps";

	private static readonly string OPTION_DESCRIPTION_ASSUME_CONTIGUOUS_FUNCTIONS =
		"Signals to assume all function bodies are contiguous " +
			"and all jumps across other functions should be treated as a call-return.";

	private static readonly string OPTION_DESCRIPTION_CONSIDER_CONDITIONAL_BRANCHES_FUNCTIONS =
		"Signals to allow conditional jumps to be consider for " +
			"shared return jumps to other functions.";

	private static bool OPTION_DEFAULT_ASSUME_CONTIGUOUS_FUNCTIONS_ENABLED = true;
	private static bool OPTION_DEFAULT_CONSIDER_CONDITIONAL_BRANCHES_ENABLED = false;

	private bool assumeContiguousFunctions = OPTION_DEFAULT_ASSUME_CONTIGUOUS_FUNCTIONS_ENABLED;
	private bool considerConditionalBranches =
		OPTION_DEFAULT_CONSIDER_CONDITIONAL_BRANCHES_ENABLED;

	public SharedReturnAnalyzer() : this(NAME, DESCRIPTION, AnalyzerType.FUNCTION_ANALYZER)
    {
	}

	public SharedReturnAnalyzer(string name, string description, AnalyzerType analyzerType) : base(name, description, analyzerType)
    {
		setPriority(AnalysisPriority.CODE_ANALYSIS.before().before());
		setSupportsOneTimeAnalysis();
	}

	/* @Override */
	public bool added(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log)
    {

		SharedReturnAnalysisCmd cmd = new SharedReturnAnalysisCmd(set, assumeContiguousFunctions,
			considerConditionalBranches);
		cmd.applyTo(program);

		return true;
	}

	/* @Override */
	public bool getDefaultEnablement(Program program) {
		Language language = program.getLanguage();

		bool sharedReturnEnabled = language.getPropertyAsBoolean(
			GhidraLanguagePropertyKeys.ENABLE_SHARED_RETURN_ANALYSIS, true);
		if (GoRttiMapper.isGolangProgram(program)) {
			sharedReturnEnabled = false;
		}

		// If the language (in the .pspec file) overrides this setting, use that value
		bool contiguousFunctionsEnabled = language.getPropertyAsBoolean(
			GhidraLanguagePropertyKeys.ENABLE_ASSUME_CONTIGUOUS_FUNCTIONS_ONLY,
			assumeContiguousFunctions);

		assumeContiguousFunctions = contiguousFunctionsEnabled;

		return sharedReturnEnabled;
	}

	/* @Override */
	public void registerOptions(Options options, Program program) {
		HelpLocation helpLocation = new HelpLocation("AutoAnalysisPlugin",
			"Auto_Analysis_Option_Instructions");

		options.registerOption(OPTION_NAME_ASSUME_CONTIGUOUS_FUNCTIONS,
			assumeContiguousFunctions, helpLocation,
			OPTION_DESCRIPTION_ASSUME_CONTIGUOUS_FUNCTIONS);

		options.registerOption(OPTION_NAME_CONSIDER_CONDITIONAL_BRANCHES_FUNCTIONS,
			considerConditionalBranches, helpLocation,
			OPTION_DESCRIPTION_CONSIDER_CONDITIONAL_BRANCHES_FUNCTIONS);
	}

	/* @Override */
	public void optionsChanged(Options options, Program program) {

		assumeContiguousFunctions = options.getBoolean(OPTION_NAME_ASSUME_CONTIGUOUS_FUNCTIONS,
			assumeContiguousFunctions);

		considerConditionalBranches =
			options.getBoolean(OPTION_NAME_CONSIDER_CONDITIONAL_BRANCHES_FUNCTIONS,
				considerConditionalBranches);

	}

}
